{"path": "textutils.py", "content": "import re
from collections import Counter

# A word is a run of letters, digits and apostrophes (underscore excluded).
_WORD_RE = re.compile(r"(?:[^\W_]|')+")


def words(text):
    return text.split()


def word_count(text):
    """Map lower-cased words to their counts, ignoring punctuation."""
    tokens = (t for t in _WORD_RE.findall(text.lower()) if t.strip("'"))
    return dict(Counter(tokens))
"}

