from textutils import words, word_count


class T(unittest.TestCase):
    def test_words(self):
        self.assertEqual(words('a b'), ['a', 'b'])

    def test_word_count(self):
        self.assertEqual(
            word_count("Hello, hello! It's 2 o'clock; HELLO 2."),
            {'hello': 3, "it's": 1, '2': 2, "o'clock": 1},
        )

    def test_word_count_empty_and_punctuation_only(self):
        self.assertEqual(word_count(''), {})
        self.assertEqual(word_count("... ' -- _"), {})


if __name__ == '__main__':
    unittest.main()
"}
